// table schema generated by introspection
import {
  pgTable,
  unique,
  integer,
  varchar,
  text,
  timestamp,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

export const contextsTable = pgTable(
  "contexts",
  {
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    name: varchar("name", { length: 255 }).notNull(),
    context: text("context").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
  },
  (table) => [unique("contexts_id_unique").on(table.id)],
);

// 사용자별 선택된 LLM 모델을 저장하는 테이블
export const userModelsTable = pgTable("user_models", {
  name: varchar({ length: 255 }).primaryKey(),
  model: varchar({ length: 255 }).notNull(),
});

// 사용자별 선택된 시스템 프롬프트(페르소나)를 저장하는 테이블
export const userPersonasTable = pgTable("user_personas", {
  name: varchar({ length: 255 }).primaryKey(),
  personaId: varchar("persona_id", { length: 64 }).default("girlfriend").notNull(),
  customPrompt: text("custom_prompt"),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
});

// 음성 채널 대화록(STT/TTS 로그)을 대시보드 전용으로 저장하는 테이블
export const voiceLogsTable = pgTable("voice_logs", {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  guildName: varchar("guild_name", { length: 255 }).notNull(),
  channelName: varchar("channel_name", { length: 255 }).notNull(),
  userName: varchar("user_name", { length: 255 }).notNull(),
  userText: text("user_text").notNull(),
  botReply: text("bot_reply").notNull(),
  actionType: varchar("action_type", { length: 50 }).default("chat").notNull(),
  durationSec: varchar("duration_sec", { length: 32 }),
  createdAt: timestamp("created_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
});

// 사용자별 개인화 장기 기억(RAG)을 저장하는 테이블
export const userMemoriesTable = pgTable("user_memories", {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  userName: varchar("user_name", { length: 255 }).notNull(),
  memory: text("memory").notNull(),
  category: varchar("category", { length: 50 }).default("general").notNull(),
  importance: integer("importance").default(3).notNull(),
  embedding: text("embedding"), // Float 배열의 JSON 직렬화
  createdAt: timestamp("created_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
});

// 봇 시스템 전역 설정(목소리 프리셋, 기본 페르소나 등)을 영구 저장하는 테이블
export const botSettingsTable = pgTable("bot_settings", {
  key: varchar("key", { length: 128 }).primaryKey(),
  value: text("value").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
});


